def solve(grid):
    rows = len(grid)
    cols = len(grid[0])

    points = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0:
                points.append((r, c, grid[r][c]))

    (r1, c1, a), (r2, c2, b) = points
    result = [[0]*cols for _ in range(rows)]
    arm = 2

    if c1 == c2:
        if r1 > r2:
            r1, r2, a, b = r2, r1, b, a
        c = c1
        D = r2 - r1
        travel = (D - 3) // 2
        bar_A = r1 + travel
        bar_B = r2 - travel
        for r in range(r1, bar_A + 1):
            result[r][c] = a
        for r in range(bar_B, r2 + 1):
            result[r][c] = b
        for cc in range(c - arm, c + arm + 1):
            result[bar_A][cc] = a
            result[bar_B][cc] = b
        mid = (bar_A + bar_B) / 2
        for r in range(bar_A + 1, bar_B):
            color = a if r < mid else b
            result[r][c - arm] = color
            result[r][c + arm] = color
    else:
        if c1 > c2:
            c1, c2, a, b = c2, c1, b, a
        r = r1
        D = c2 - c1
        travel = (D - 3) // 2
        bar_A = c1 + travel
        bar_B = c2 - travel
        for cc in range(c1, bar_A + 1):
            result[r][cc] = a
        for cc in range(bar_B, c2 + 1):
            result[r][cc] = b
        for rr in range(r - arm, r + arm + 1):
            result[rr][bar_A] = a
            result[rr][bar_B] = b
        mid = (bar_A + bar_B) / 2
        for cc in range(bar_A + 1, bar_B):
            color = a if cc < mid else b
            result[r - arm][cc] = color
            result[r + arm][cc] = color

    return result
